-- PLAN ONLY — not applied. Target schema once a server database is approved.
-- Every business table carries tenant_id; RLS restricts rows to members of that tenant.
-- Marketplace API secrets live in a separate table readable only by service_role (never by the browser).

create table tenants (id uuid primary key default gen_random_uuid(), name text not null, owner_id uuid not null references auth.users(id), created_at timestamptz default now());
create table tenant_members (tenant_id uuid references tenants(id) on delete cascade, user_id uuid references auth.users(id) on delete cascade, primary key (tenant_id, user_id));
create table stores (id uuid primary key default gen_random_uuid(), tenant_id uuid not null references tenants(id) on delete cascade, name text not null, marketplace text not null, connection_status text not null default 'not_connected', created_at timestamptz default now());
create table marketplace_credentials (store_id uuid primary key references stores(id) on delete cascade, seller_id text not null, api_key_encrypted text not null, api_secret_encrypted text not null, updated_at timestamptz default now());
create table products (id uuid primary key default gen_random_uuid(), tenant_id uuid not null, store_id uuid not null references stores(id) on delete cascade, name text not null, sku text not null, barcode text, unit_cost numeric(14,2), vat_rate int not null, source text not null default 'manual', verified boolean not null default false, unique (store_id, sku));
create table order_records (id uuid primary key default gen_random_uuid(), tenant_id uuid not null, store_id uuid not null references stores(id) on delete cascade, type text not null check (type in ('sale','return','cancellation')), order_number text not null, date date not null, product_id uuid references products(id) on delete set null, quantity int not null check (quantity > 0), gross_amount numeric(14,2) not null, discount_amount numeric(14,2) not null default 0, coupon_amount numeric(14,2) not null default 0, commission_amount numeric(14,2) not null default 0, shipping_amount numeric(14,2) not null default 0, withholding_amount numeric(14,2) not null default 0, note text, source text not null default 'manual', verified boolean not null default false);
create table expenses (id uuid primary key default gen_random_uuid(), tenant_id uuid not null, store_id uuid references stores(id) on delete cascade, date date not null, category text not null, amount numeric(14,2) not null check (amount > 0), description text not null, source text not null default 'manual');
create table reconciliations (id uuid primary key default gen_random_uuid(), tenant_id uuid not null, store_id uuid not null references stores(id) on delete cascade, period char(7) not null, totals jsonb not null, source text not null default 'manual', note text, unique (store_id, period));
-- GRANTs + RLS: authenticated may CRUD rows where tenant_id is one of their tenant_members rows;
-- marketplace_credentials: no grants to anon/authenticated, service_role only.
